    {
      "keystrokes": "cat <<'CPP' > timetable.cpp\n#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int n; long long t;\n    if(!(cin >> n >> t)) return 0;\n    vector<long long> a(n+1), x(n+1);\n    for(int i = 1; i <= n; ++i) cin >> a[i];\n    for(int i = 1; i <= n; ++i) cin >> x[i];\n\n    // Feasibility checks: x should be nondecreasing and x[i] >= i\n    for(int i = 2; i <= n; ++i) {\n        if(x[i] < x[i-1]) {\n            cout << \"No\\n\";\n            return 0;\n        }\n    }\n    for(int i = 1; i <= n; ++i) {\n        if(x[i] < i) {\n            cout << \"No\\n\";\n            return 0;\n        }\n    }\n\n    // Compute c_i = a_i + t and build needs per x_i\n    vector<long long> need(n+1, 0);\n    for(int i = 1; i <= n; ++i) {\n        long long c = a[i] + t;\n        int k = (int)x[i];\n        if(c > need[k]) need[k] = c;\n    }\n\n    vector<long long> pref(n+1, 0);\n    long long mx = 0;\n    for(int k = 1; k <= n; ++k) {\n        mx = max(mx, need[k]);\n        pref[k] = mx;\n    }\n\n    // Build b with strict increasing property\n    vector<long long> b(n+1, 0);\n    if(n >= 1) {\n        b[1] = max(pref[1], 1LL);\n        for(int k = 2; k <= n; ++k) b[k] = max(pref[k], b[k-1] + 1);\n    }\n\n    cout << \"Yes\\n\";\n    for(int i = 1; i <= n; ++i) cout << b[i] << (i==n ? '\\n' : ' ');\n\n    return 0;\n}\nCPP\n\ng++ -std=c++17 timetable.cpp -O2 -pipe -static -s -o timetable\n\n./timetable << EOF\n3 10\n4 6 8\n2 2 3\nEOF"
